/* the name of type riscos, or NULL if it is not allocated: skip the names of
 * the allocated types below it in its block */
static const char *filetype_name(unsigned short riscos)
{
  uint64_t    bits;
  uint64_t    bit;
  const char *name;
  int         skip;

  if (riscos >= NELEMS(g_types) * 64)
    return NULL;

  bits = g_types[riscos >> 6];
  bit  = (uint64_t) 1 << (riscos & 63);
  if ((bits & bit) == 0)
    return NULL;

  name = g_names[riscos >> 6];
  for (skip = countbits_64(bits & (bit - 1)); skip > 0; skip--)
    name += strlen(name) + 1;

  return name;
}

/* the canonical extension of type riscos, or "": its first in g_exts */
static const char *filetype_ext(unsigned short riscos)
{
  const char *ext;
  size_t      i;

  ext = g_exts;
  for (i = 0; i < NELEMS(g_ext_types); i++)
  {
    if (g_ext_types[i] == riscos)
      return ext;
    ext += strlen(ext) + 1;
  }

  return "";
}

filetype_t filetype_from_riscos(unsigned short riscos)
{
  filetype_t type;

  type.riscos = riscos;
  type.ext    = filetype_ext(riscos);
  type.name   = filetype_name(riscos);
  if (type.name == NULL)
    type.name = "";

  return type;
}

filetype_t filetype_from_ext(const char *ext)
{
  const char *pool;
  size_t      i;

  if (ext == NULL)
    return filetype_DATA;

  if (ext[0] == '.')
    ext++;

  pool = g_exts;
  for (i = 0; i < NELEMS(g_ext_types); i++)
  {
    if (strcasecmp(pool, ext) == 0)
      return filetype_from_riscos(g_ext_types[i]);
    pool += strlen(pool) + 1;
  }

  return filetype_DATA;
}

result_t filetype_set(const char *path, filetype_t type)
{
  if (path == NULL)
    return result_NULL_ARG;

#ifdef __riscos

  {
    _kernel_oserror *err;

    /* OS_File 18: set a file's type. */
    err = _swix(OS_File, _INR(0,2), 18, path, type.riscos);
    if (err != NULL)
      return result_FILE_NOT_FOUND;
  }

#else

  NOT_USED(type);

#endif

  return result_OK;
}
